using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "RedemptionInscriptionEffect", menuName = "Data/Battle/Effects/Orion/RedemptionInscription Effect")]
public class RedemptionInscriptionEffect : Effect
{
	[Header("RedemptionInscription Effect")]
	[SerializeField]
	private KarmaEffect karmaEffect;

	[SerializeField]
	private GainOtherEffectEffect gainOtherEffectEffect;

	[SerializeField]
	private ActivateStarAbility activateStarAbility;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return gainOtherEffectEffect.GetInscriptionBaseDescription(activateStarAbility, base.localizationManager.GetLocalizedDecreaseEffect(karmaEffect, amount)) + AppendedDescription();
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		effectOwner.GetComponent<UnitEffects>().IsEffectActiveAndDecreaseEffect(karmaEffect, effectAmount);
		return effectAmount;
	}
}
